package com.recipetracker;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

final class ItemIndex
{
	private final Map<String, Integer> byName;
	private final Map<Integer, String> byId;

	private ItemIndex(Map<String, Integer> byName, Map<Integer, String> byId)
	{
		this.byName = Collections.unmodifiableMap(byName);
		this.byId = Collections.unmodifiableMap(byId);
	}

	static ItemIndex build(ItemManager itemManager, int itemCount)
	{
		Map<String, Integer> names = new LinkedHashMap<>();
		Map<Integer, String> ids = new LinkedHashMap<>();
		for (int id = 0; id < itemCount; id++)
		{
			try
			{
				ItemComposition composition = itemManager.getItemComposition(id);
				String name = composition == null ? null : composition.getName();
				if (name == null || name.isEmpty() || "null".equalsIgnoreCase(name) || name.startsWith("<"))
				{
					continue;
				}
				int canonical = itemManager.canonicalize(id);
				names.putIfAbsent(normalize(name), canonical);
				ids.putIfAbsent(canonical, name);
			}
			catch (RuntimeException ignored)
			{
				// Sparse/invalid cache IDs are expected.
			}
		}
		return new ItemIndex(names, ids);
	}

	int findId(String name)
	{
		return byName.getOrDefault(normalize(name), -1);
	}

	String findName(int id)
	{
		return byId.get(id);
	}

	private static String normalize(String name)
	{
		return name == null ? "" : name.replace('\u00a0', ' ').trim().toLowerCase(Locale.ENGLISH);
	}
}

package com.recipetracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

public final class MaterialCalculator
{
	private MaterialCalculator()
	{
	}

	public static List<MaterialStatus> calculate(Recipe recipe, int targetQuantity,
		Map<Integer, Integer> inventory)
	{
		if (recipe == null)
		{
			return Collections.emptyList();
		}

		return calculateDirect(new TrackedRecipe(recipe, targetQuantity), inventory,
			Collections.emptyMap());
	}

	static List<MaterialStatus> calculateDirect(TrackedRecipe tracked,
		Map<Integer, Integer> inventory, Map<Integer, Integer> bank)
	{
		Map<String, RequirementTotal> totals = new LinkedHashMap<>();
		int crafts = craftsFor(tracked.getRecipe(), tracked.getQuantity());
		for (MaterialRequirement material : tracked.getRecipe().getMaterials())
		{
			add(totals, material, required(material, crafts), false);
		}
		for (MaterialRequirement tool : tracked.getRecipe().getTools())
		{
			add(totals, tool, 1, true);
		}
		return statuses(totals, inventory, bank);
	}

	public static List<MaterialStatus> calculateAll(List<TrackedRecipe> trackedRecipes,
		Map<Integer, Integer> inventory)
	{
		return calculateAll(trackedRecipes, inventory, Collections.emptyMap());
	}

	public static List<MaterialStatus> calculateAll(List<TrackedRecipe> trackedRecipes,
		Map<Integer, Integer> inventory, Map<Integer, Integer> bank)
	{
		Map<String, RequirementTotal> totals = new LinkedHashMap<>();
		for (TrackedRecipe tracked : trackedRecipes)
		{
			Set<TrackedRecipe> ancestors = Collections.newSetFromMap(new IdentityHashMap<>());
			accumulate(tracked, tracked.getQuantity(), totals, ancestors);
		}
		return statuses(totals, inventory, bank);
	}

	private static void accumulate(TrackedRecipe tracked, int targetQuantity,
		Map<String, RequirementTotal> totals, Set<TrackedRecipe> ancestors)
	{
		if (!ancestors.add(tracked))
		{
			return;
		}
		Recipe recipe = tracked.getRecipe();
		int crafts = craftsFor(recipe, targetQuantity);
		for (MaterialRequirement material : recipe.getMaterials())
		{
			int amount = required(material, crafts);
			TrackedRecipe child = tracked.childFor(material);
			if (child == null)
			{
				add(totals, material, amount, false);
			}
			else
			{
				accumulate(child, amount, totals, ancestors);
			}
		}
		for (MaterialRequirement tool : recipe.getTools())
		{
			add(totals, tool, 1, true);
		}
		ancestors.remove(tracked);
	}

	private static List<MaterialStatus> statuses(Map<String, RequirementTotal> totals,
		Map<Integer, Integer> inventory, Map<Integer, Integer> bank)
	{
		List<MaterialStatus> result = new ArrayList<>();
		for (RequirementTotal total : totals.values())
		{
			int inInventory = 0;
			int inBank = 0;
			for (int acceptedId : total.requirement.getAcceptedItemIds())
			{
				inInventory += inventory.getOrDefault(acceptedId, 0);
				inBank += bank.getOrDefault(acceptedId, 0);
			}
			result.add(new MaterialStatus(total.requirement.getItemId(), total.requirement.getName(),
				total.required, inInventory, inBank, total.tool));
		}
		return Collections.unmodifiableList(result);
	}

	private static int craftsFor(Recipe recipe, int targetQuantity)
	{
		return Math.max(1, (targetQuantity + recipe.getOutputQuantity() - 1)
			/ recipe.getOutputQuantity());
	}

	private static int required(MaterialRequirement material, int crafts)
	{
		return (int) Math.ceil(material.getQuantityPerCraft() * crafts);
	}

	private static void add(Map<String, RequirementTotal> totals, MaterialRequirement requirement,
		int amount, boolean tool)
	{
		String key = requirement.getItemId() > 0 ? "id:" + requirement.getItemId()
			: "name:" + requirement.getName().toLowerCase(Locale.ENGLISH);
		RequirementTotal total = totals.get(key);
		if (total == null)
		{
			totals.put(key, new RequirementTotal(requirement, amount, tool));
		}
		else if (!tool)
		{
			total.required += amount;
		}
	}

	private static final class RequirementTotal
	{
		private final MaterialRequirement requirement;
		private int required;
		private final boolean tool;

		private RequirementTotal(MaterialRequirement requirement, int required, boolean tool)
		{
			this.requirement = requirement;
			this.required = required;
			this.tool = tool;
		}
	}
}

package com.recipetracker;

import java.util.Objects;

public final class MaterialRequirement
{
	private final int itemId;
	private final int[] acceptedItemIds;
	private final String name;
	private final double quantityPerCraft;

	public MaterialRequirement(int itemId, String name, int quantity)
	{
		this(itemId, name, quantity, new int[0]);
	}

	public MaterialRequirement(int itemId, String name, int quantity, int... alternativeItemIds)
	{
		this(itemId, name, (double) quantity, alternativeItemIds);
	}

	public MaterialRequirement(int itemId, String name, double quantity, int... alternativeItemIds)
	{
		this.itemId = itemId;
		this.acceptedItemIds = new int[alternativeItemIds.length + 1];
		this.acceptedItemIds[0] = itemId;
		System.arraycopy(alternativeItemIds, 0, acceptedItemIds, 1, alternativeItemIds.length);
		this.name = Objects.requireNonNull(name);
		this.quantityPerCraft = quantity;
	}

	public int[] getAcceptedItemIds()
	{
		return acceptedItemIds.clone();
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getName()
	{
		return name;
	}

	public int getQuantity()
	{
		return (int) Math.ceil(quantityPerCraft);
	}

	public double getQuantityPerCraft()
	{
		return quantityPerCraft;
	}
}

package com.recipetracker;

public final class MaterialStatus
{
	private final int itemId;
	private final String name;
	private final int required;
	private final int inInventory;
	private final int inBank;
	private final boolean tool;

	public MaterialStatus(String name, int required, int inInventory)
	{
		this(-1, name, required, inInventory, 0, false);
	}

	public MaterialStatus(int itemId, String name, int required, int inInventory, boolean tool)
	{
		this(itemId, name, required, inInventory, 0, tool);
	}

	public MaterialStatus(int itemId, String name, int required, int inInventory, int inBank, boolean tool)
	{
		this.itemId = itemId;
		this.name = name;
		this.required = required;
		this.inInventory = inInventory;
		this.inBank = inBank;
		this.tool = tool;
	}

	public int getItemId()
	{
		return itemId;
	}

	public boolean isTool()
	{
		return tool;
	}

	public String getName()
	{
		return name;
	}

	public int getRequired()
	{
		return required;
	}

	public int getInInventory()
	{
		return inInventory;
	}

	public int getInBank()
	{
		return inBank;
	}

	public boolean isComplete()
	{
		return inInventory >= required;
	}

	public boolean isAvailable()
	{
		return (long) inInventory + inBank >= required;
	}
}

package com.recipetracker;

import java.util.Locale;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class NativeRecipeCapture
{
	private static final Pattern MATERIALS_MESSAGE = Pattern.compile(
		"^(.+?)\\s+materials:\\s*(.+?)\\.?$", Pattern.CASE_INSENSITIVE);
	private static final Pattern MATERIAL = Pattern.compile(
		"^(.+?)\\s+x\\s+([0-9][0-9,]*)$", Pattern.CASE_INSENSITIVE);

	private NativeRecipeCapture()
	{
	}

	static Optional<RecipeDefinition> parseSailingMaterials(String message)
	{
		if (message == null)
		{
			return Optional.empty();
		}

		Matcher messageMatcher = MATERIALS_MESSAGE.matcher(message.trim());
		if (!messageMatcher.matches())
		{
			return Optional.empty();
		}

		String outputName = messageMatcher.group(1).trim();
		if (outputName.isEmpty())
		{
			return Optional.empty();
		}

		RecipeDefinition definition = new RecipeDefinition();
		definition.name = outputName;
		definition.category = "Sailing";
		definition.outputQuantity = 1;
		StringBuilder variant = new StringBuilder();

		// Split only on commas that introduce another material. Quantity grouping
		// commas (for example "1,250") must remain part of the quantity.
		for (String rawPart : messageMatcher.group(2).split("\\s*,\\s*(?=(?i:and\\s+)?[^0-9])"))
		{
			String part = rawPart.trim().replaceFirst("(?i)^and\\s+", "");
			Matcher materialMatcher = MATERIAL.matcher(part);
			if (!materialMatcher.matches())
			{
				return Optional.empty();
			}

			String materialName = materialMatcher.group(1).trim();
			int quantity;
			try
			{
				quantity = Integer.parseInt(materialMatcher.group(2).replace(",", ""));
			}
			catch (NumberFormatException ex)
			{
				return Optional.empty();
			}
			if (materialName.isEmpty() || quantity <= 0)
			{
				return Optional.empty();
			}

			RecipeDefinition.RequirementDefinition requirement =
				new RecipeDefinition.RequirementDefinition();
			requirement.name = materialName;
			requirement.quantity = quantity;
			definition.requirements.add(requirement);
			if (variant.length() > 0)
			{
				variant.append('-');
			}
			variant.append(materialName.toLowerCase(Locale.ENGLISH)).append('-').append(quantity);
		}

		if (definition.requirements.isEmpty())
		{
			return Optional.empty();
		}
		definition.variant = variant.toString();
		definition.key = RecipeKey.of(definition.name, definition.category, definition.variant);
		return Optional.of(definition);
	}
}

package com.recipetracker;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

public final class Recipe
{
	private final int outputItemId;
	private final String key;
	private final RecipeSource source;
	private final String name;
	private final String category;
	private final int outputQuantity;
	private final List<MaterialRequirement> materials;
	private final List<MaterialRequirement> tools;

	public Recipe(int outputItemId, String name, String category, int outputQuantity,
		MaterialRequirement... materials)
	{
		this(RecipeKey.of(name, category, ""), RecipeSource.HAND_AUTHORED,
			outputItemId, name, category, outputQuantity,
			Collections.unmodifiableList(Arrays.asList(materials)), Collections.emptyList());
	}

	Recipe(String key, RecipeSource source, int outputItemId, String name, String category, int outputQuantity,
		List<MaterialRequirement> materials, List<MaterialRequirement> tools)
	{
		this.key = Objects.requireNonNull(key);
		this.source = Objects.requireNonNull(source);
		this.outputItemId = outputItemId;
		this.name = Objects.requireNonNull(name);
		this.category = Objects.requireNonNull(category);
		this.outputQuantity = outputQuantity;
		this.materials = materials;
		this.tools = tools;
	}

	public List<MaterialRequirement> getTools()
	{
		return tools;
	}

	public Recipe withTools(MaterialRequirement... requiredTools)
	{
		return new Recipe(key, source, outputItemId, name, category, outputQuantity, materials,
			Collections.unmodifiableList(Arrays.asList(requiredTools)));
	}

	Recipe withResolvedRequirements(int resolvedOutputId, List<MaterialRequirement> resolvedMaterials,
		List<MaterialRequirement> resolvedTools)
	{
		return new Recipe(key, source, resolvedOutputId, name, category, outputQuantity,
			Collections.unmodifiableList(resolvedMaterials), Collections.unmodifiableList(resolvedTools));
	}

	public String getKey()
	{
		return key;
	}

	public RecipeSource getSource()
	{
		return source;
	}

	public int getOutputItemId()
	{
		return outputItemId;
	}

	public String getName()
	{
		return name;
	}

	public String getCategory()
	{
		return category;
	}

	public int getOutputQuantity()
	{
		return outputQuantity;
	}

	public List<MaterialRequirement> getMaterials()
	{
		return materials;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.recipetracker;

import java.util.ArrayList;
import java.util.List;

final class RecipeDefinition
{
	String key;
	String name;
	String category;
	String variant = "";
	String source;
	int outputItemId;
	int outputQuantity = 1;
	List<RequirementDefinition> requirements = new ArrayList<>();

	static final class RequirementDefinition
	{
		String name;
		int itemId;
		double quantity = 1;
		String type = "material";
		List<String> alternatives = new ArrayList<>();
		List<Integer> alternativeItemIds = new ArrayList<>();
	}
}

package com.recipetracker;

import java.util.ArrayList;
import java.util.List;

final class RecipeFile
{
	int schemaVersion = 1;
	List<RecipeDefinition> recipes = new ArrayList<>();
}

package com.recipetracker;

import java.text.Normalizer;
import java.util.Locale;

public final class RecipeKey
{
	private RecipeKey()
	{
	}

	public static String of(String outputName, String category, String variant)
	{
		return normalize(category) + ":" + normalize(outputName) + ":" + normalize(variant);
	}

	private static String normalize(String value)
	{
		String normalized = Normalizer.normalize(value == null ? "" : value, Normalizer.Form.NFKD)
			.toLowerCase(Locale.ENGLISH)
			.replaceAll("[^a-z0-9]+", "-")
			.replaceAll("(^-|-$)", "");
		return normalized.isEmpty() ? "default" : normalized;
	}
}

package com.recipetracker;

import com.google.gson.Gson;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.RuneLite;

@Singleton
public class RecipeRepository
{
	private static final int SCHEMA_VERSION = 1;
	private final Gson gson;
	private final File cacheFile = new File(new File(RuneLite.RUNELITE_DIR, "recipe-tracker"), "recipe-cache.json");
	private final Map<String, Recipe> recipesByKey = new LinkedHashMap<>();
	private final Map<String, RecipeDefinition> cachedDefinitions = new LinkedHashMap<>();
	private volatile List<Recipe> snapshot = Collections.emptyList();
	private volatile Map<Integer, Recipe> craftingRecipesByOutputId = Collections.emptyMap();
	private volatile Map<String, Recipe> craftingRecipesByName = Collections.emptyMap();
	private volatile ItemIndex itemIndex;

	@Inject
	RecipeRepository(Gson gson)
	{
		this.gson = gson;
	}

	public synchronized void initialize()
	{
		recipesByKey.clear();
		cachedDefinitions.clear();
		loadBundled();
		loadCache();
		publish();
	}

	public synchronized void setItemIndex(ItemIndex index)
	{
		itemIndex = index;
		List<Recipe> current = new ArrayList<>(recipesByKey.values());
		recipesByKey.clear();
		for (Recipe recipe : current)
		{
			merge(resolve(recipe));
		}
		publish();
	}

	public List<Recipe> recipes()
	{
		return snapshot;
	}

	public Recipe findByKey(String key)
	{
		synchronized (this)
		{
			return recipesByKey.get(key);
		}
	}

	public Recipe find(int itemId, String target)
	{
		return RecipeResolver.find(snapshot, itemId, target);
	}

	Recipe findCraftingRecipe(MaterialRequirement material)
	{
		Recipe best = null;
		Map<Integer, Recipe> byOutputId = craftingRecipesByOutputId;
		for (int acceptedId : material.getAcceptedItemIds())
		{
			Recipe candidate = byOutputId.get(acceptedId);
			if (candidate != null && (best == null || compareCraftingRecipes(candidate, best) < 0))
			{
				best = candidate;
			}
		}
		Recipe named = craftingRecipesByName.get(normalizeName(material.getName()));
		if (named != null && (best == null || compareCraftingRecipes(named, best) < 0))
		{
			best = named;
		}
		return best;
	}

	private static int compareCraftingRecipes(Recipe first, Recipe second)
	{
		if (first.getMaterials().size() != second.getMaterials().size())
		{
			return Integer.compare(first.getMaterials().size(), second.getMaterials().size());
		}
		double firstTotal = first.getMaterials().stream()
			.mapToDouble(MaterialRequirement::getQuantityPerCraft).sum();
		double secondTotal = second.getMaterials().stream()
			.mapToDouble(MaterialRequirement::getQuantityPerCraft).sum();
		int totalComparison = Double.compare(secondTotal, firstTotal);
		return totalComparison != 0 ? totalComparison
			: first.getName().compareToIgnoreCase(second.getName());
	}

	public synchronized Recipe addDefinition(RecipeDefinition definition, RecipeSource source, boolean persist)
	{
		definition.source = source.name();
		Recipe recipe = toRecipe(definition, source);
		merge(recipe);
		if (persist)
		{
			cachedDefinitions.put(recipe.getKey(), definition);
			writeCache();
		}
		publish();
		return recipesByKey.get(recipe.getKey());
	}

	public int findItemId(String name)
	{
		ItemIndex index = itemIndex;
		return index == null ? -1 : index.findId(name);
	}

	public String findItemName(int id)
	{
		ItemIndex index = itemIndex;
		return index == null ? null : index.findName(id);
	}

	private void loadBundled()
	{
		try (InputStream stream = RecipeRepository.class.getResourceAsStream("recipes.json"))
		{
			if (stream == null)
			{
				return;
			}
			try (Reader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
			{
				mergeFile(gson.fromJson(reader, RecipeFile.class), RecipeSource.BUNDLED_WIKI, false);
			}
		}
		catch (IOException | RuntimeException ignored)
		{
			// A missing or malformed bundle must not prevent cached/live recipes.
		}
	}

	private void loadCache()
	{
		if (!cacheFile.isFile())
		{
			return;
		}
		try (Reader reader = new FileReader(cacheFile))
		{
			mergeFile(gson.fromJson(reader, RecipeFile.class), RecipeSource.WIKI_CACHE, true);
		}
		catch (IOException | RuntimeException ignored)
		{
			// A stale cache must not prevent startup.
		}
	}

	private void mergeFile(RecipeFile file, RecipeSource source, boolean rememberForCache)
	{
		if (file == null || file.schemaVersion != SCHEMA_VERSION || file.recipes == null)
		{
			return;
		}
		for (RecipeDefinition definition : file.recipes)
		{
			try
			{
				if (rememberForCache && definition.source != null
					&& !RecipeSource.WIKI_CACHE.name().equals(definition.source)
					&& !RecipeSource.NATIVE_CAPTURE.name().equals(definition.source))
				{
					continue;
				}
				RecipeSource effectiveSource = source;
				if (definition.source != null)
				{
					try
					{
						effectiveSource = RecipeSource.valueOf(definition.source);
					}
					catch (IllegalArgumentException ignored) { }
				}
				Recipe recipe = toRecipe(definition, effectiveSource);
				merge(recipe);
				if (rememberForCache)
				{
					cachedDefinitions.put(recipe.getKey(), definition);
				}
			}
			catch (RuntimeException ignored)
			{
				// Invalid rows are isolated instead of discarding the complete file.
			}
		}
	}

	private Recipe toRecipe(RecipeDefinition definition, RecipeSource source)
	{
		String key = definition.key == null || definition.key.trim().isEmpty()
			? RecipeKey.of(definition.name, definition.category, definition.variant) : definition.key;
		List<MaterialRequirement> materials = new ArrayList<>();
		List<MaterialRequirement> tools = new ArrayList<>();
		for (RecipeDefinition.RequirementDefinition requirement : definition.requirements)
		{
			int primaryId = resolveId(requirement.itemId, requirement.name);
			List<Integer> alternatives = new ArrayList<>(requirement.alternativeItemIds);
			for (String alternative : requirement.alternatives)
			{
				int id = resolveId(0, alternative);
				if (id > 0)
				{
					alternatives.add(id);
				}
			}
			int[] ids = alternatives.stream().mapToInt(Integer::intValue).toArray();
			MaterialRequirement converted = new MaterialRequirement(primaryId, requirement.name,
				requirement.quantity, ids);
			("tool".equalsIgnoreCase(requirement.type) ? tools : materials).add(converted);
		}
		int outputId = resolveId(definition.outputItemId, definition.name);
		return new Recipe(key, source, outputId, definition.name, definition.category,
			Math.max(1, definition.outputQuantity), Collections.unmodifiableList(materials),
			Collections.unmodifiableList(tools));
	}

	private Recipe resolve(Recipe recipe)
	{
		int outputId = resolveId(recipe.getOutputItemId(), recipe.getName());
		return recipe.withResolvedRequirements(outputId, resolve(recipe.getMaterials()), resolve(recipe.getTools()));
	}

	private List<MaterialRequirement> resolve(Collection<MaterialRequirement> requirements)
	{
		List<MaterialRequirement> result = new ArrayList<>();
		for (MaterialRequirement requirement : requirements)
		{
			int[] accepted = requirement.getAcceptedItemIds();
			List<Integer> alternatives = new ArrayList<>();
			for (int acceptedId : accepted)
			{
				if (acceptedId > 0 && acceptedId != requirement.getItemId()) alternatives.add(acceptedId);
			}
			result.add(new MaterialRequirement(resolveId(requirement.getItemId(), requirement.getName()),
				requirement.getName(), requirement.getQuantityPerCraft(),
				alternatives.stream().mapToInt(Integer::intValue).toArray()));
		}
		return result;
	}

	private int resolveId(int existingId, String name)
	{
		if (existingId > 0)
		{
			return existingId;
		}
		ItemIndex index = itemIndex;
		return index == null ? -1 : index.findId(name);
	}

	private void merge(Recipe recipe)
	{
		Recipe current = recipesByKey.get(recipe.getKey());
		if (current == null || recipe.getSource().getPriority() >= current.getSource().getPriority())
		{
			recipesByKey.put(recipe.getKey(), recipe);
		}
	}

	private void publish()
	{
		List<Recipe> recipes = new ArrayList<>(recipesByKey.values());
		recipes.sort(Comparator.comparing(Recipe::getCategory).thenComparing(Recipe::getName));
		Map<Integer, Recipe> byOutputId = new LinkedHashMap<>();
		Map<String, Recipe> byName = new LinkedHashMap<>();
		for (Recipe recipe : recipes)
		{
			if (recipe.getMaterials().isEmpty())
			{
				continue;
			}
			if (recipe.getOutputItemId() > 0)
			{
				byOutputId.merge(recipe.getOutputItemId(), recipe, RecipeRepository::preferredCraftingRecipe);
			}
			byName.merge(normalizeName(recipe.getName()), recipe, RecipeRepository::preferredCraftingRecipe);
		}
		snapshot = Collections.unmodifiableList(recipes);
		craftingRecipesByOutputId = Collections.unmodifiableMap(byOutputId);
		craftingRecipesByName = Collections.unmodifiableMap(byName);
	}

	private static Recipe preferredCraftingRecipe(Recipe first, Recipe second)
	{
		return compareCraftingRecipes(first, second) <= 0 ? first : second;
	}

	private static String normalizeName(String name)
	{
		return name == null ? "" : name.trim().toLowerCase(Locale.ENGLISH);
	}

	private void writeCache()
	{
		File directory = cacheFile.getParentFile();
		if (!directory.isDirectory() && !directory.mkdirs())
		{
			return;
		}
		RecipeFile file = new RecipeFile();
		file.recipes.addAll(cachedDefinitions.values());
		try (FileWriter writer = new FileWriter(cacheFile))
		{
			gson.toJson(file, writer);
		}
		catch (IOException ignored)
		{
			// The in-memory recipe remains usable if persistence fails.
		}
	}
}

package com.recipetracker;

import java.util.List;
import java.util.Locale;

final class RecipeResolver
{
	private RecipeResolver()
	{
	}

	static Recipe find(List<Recipe> recipes, int itemId, String menuTarget)
	{
		for (Recipe recipe : recipes)
		{
			if (recipe.getOutputItemId() == itemId)
			{
				return recipe;
			}
		}

		String targetName = normalize(menuTarget);
		Recipe match = null;
		for (Recipe recipe : recipes)
		{
			String recipeName = normalize(recipe.getName());
			if (recipeName.equals(targetName)
				|| (!recipeName.isEmpty() && targetName.contains(recipeName)))
			{
				if (match != null)
				{
					return null;
				}
				match = recipe;
			}
		}
		return match;
	}

	private static String normalize(String value)
	{
		if (value == null)
		{
			return "";
		}

		return value
			.replaceAll("<[^>]*>", "")
			.replace('\u00a0', ' ')
			.toLowerCase(Locale.ENGLISH)
			.replace(" (flatpack)", "")
			.replace(" (boat facility)", "")
			.trim()
			.replaceAll("\\s+", " ");
	}
}

